"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["31952"],{83494(e){e.exports=JSON.parse('{"id":13154,"title":"produit gel douche","description":"Une photographie publicitaire ultra luxueuse, photor\xe9aliste et cin\xe9matographique mettant en sc\xe8ne quatre bouteilles premium de gel douche \u201CJ\u2019aime\u201D de 1 litre avec pompes noires \xe9l\xe9gantes, align\xe9es dans une composition harmonieuse et sophistiqu\xe9e sur une grande surface en marbre blanc poli avec de fines veines grises naturelles. Style campagne cosm\xe9tique haut de gamme, ambiance spa tropical premium, rendu hyper r\xe9aliste, textures ultra d\xe9taill\xe9es, reflets r\xe9alistes, condensation naturelle et \xe9clairage cin\xe9matographique.\\n\\nIMPORTANT : utiliser exactement les images de r\xe9f\xe9rence des produits. Pr\xe9server \xe0 100% la forme des bouteilles, les proportions, les \xe9tiquettes, les logos, la typographie, les couleurs, les illustrations, les d\xe9tails imprim\xe9s, la transparence du plastique, les tons des liquides et les pompes noires sans aucune modification ni redesign. Toutes les \xe9tiquettes doivent rester parfaitement nettes, lisibles et identiques aux r\xe9f\xe9rences originales.\\n\\nIMPORTANT ABSOLU : les quatre bouteilles doivent avoir EXACTEMENT la m\xeame taille, la m\xeame hauteur, la m\xeame largeur, la m\xeame forme, la m\xeame perspective et les m\xeames proportions. Aucun flacon ne doit para\xeetre plus grand ou plus petit. Les pompes noires doivent \xeatre parfaitement align\xe9es au m\xeame niveau horizontal. Les bouteilles doivent former une gamme parfaitement uniforme et \xe9quilibr\xe9e comme dans une publicit\xe9 professionnelle de cosm\xe9tique premium. Respect strict de l\u2019\xe9chelle identique entre tous les flacons.\\n\\nIMPORTANT COMPOSITION : les fruits et \xe9l\xe9ments d\xe9coratifs doivent \xeatre principalement plac\xe9s derri\xe8re les bouteilles et l\xe9g\xe8rement autour de leur base, sans cacher les \xe9tiquettes. Les fruits doivent cr\xe9er un arri\xe8re-plan vivant et \xe9l\xe9gant, avec une disposition flottante et naturelle donnant de la profondeur \xe0 la sc\xe8ne. Quelques fruits peuvent appara\xeetre l\xe9g\xe8rement sur les c\xf4t\xe9s du premier plan, mais la majorit\xe9 des \xe9l\xe9ments fruit\xe9s doit rester derri\xe8re les bouteilles pour mettre les produits au centre de l\u2019attention.\\n\\nDE GAUCHE \xc0 DROITE :\\n\\n1\uFE0F\u20E3 GRENADE \u2014 Gel Douche Hydratant\\nGrande bouteille transparente remplie d\u2019un liquide rose-rouge luxueux avec l\u2019\xe9tiquette exacte : \u201CGRENADE Gel Douche HYDRATANT\u201D, logo noir \u201Cmg\u201D et \xe9criture \xe9l\xe9gante \u201CJ\u2019aime\u201D.\\nDerri\xe8re la bouteille : grenades fra\xeeches enti\xe8res et ouvertes, graines rouge rubis brillantes, ambiance spa chaleureuse avec bougie douce et serviettes blanches floues en arri\xe8re-plan.\\n\\n2\uFE0F\u20E3 POPEYE & MANGUE \u2014 Gel Douche Tropical\\nGrande bouteille transparente contenant un liquide orange mangue \xe9clatant avec l\u2019\xe9tiquette exacte : \u201CPOPEYE & MANGUE Gel Douche Tropical\u201D.\\nDerri\xe8re la bouteille : mangues, papayes ouvertes, feuilles tropicales luxuriantes et v\xe9g\xe9tation exotique l\xe9g\xe8rement floue avec lumi\xe8re chaude traversant les palmiers.\\n\\n3\uFE0F\u20E3 POMME & ANANAS \u2014 Gel Douche D\xe9tente & Hydrate\\nGrande bouteille transparente remplie d\u2019un liquide jaune ananas lumineux avec l\u2019\xe9tiquette exacte : \u201CPOMME & ANANAS Gel Douche DETENTE & HYDRATE\u201D.\\nDerri\xe8re la bouteille : pommes vertes, ananas entiers et coup\xe9s, l\xe9g\xe8re brume d\u2019eau tropicale et fines particules d\u2019humidit\xe9 lumineuses.\\n\\n4\uFE0F\u20E3 FRA\xceCHEUR MARINE \u2014 Gel Douche Rafra\xeechissant\\nGrande bouteille transparente remplie d\u2019un liquide bleu oc\xe9an lumineux avec l\u2019\xe9tiquette exacte : \u201CFRA\xceCHEUR MARINE Gel Douche RAFRA\xceCHISSANT\u201D.\\nDerri\xe8re la bouteille : coquillages marins, \xe9toile de mer bleue, verre poli bleu, coraux d\xe9coratifs et vue oc\xe9anique douce en arri\xe8re-plan.\\n\\n\xc9CLAIRAGE ET COMPOSITION :\\nLes quatre bouteilles sont parfaitement centr\xe9es et dominent visuellement la sc\xe8ne. Les fruits et accessoires d\xe9coratifs restent secondaires et cr\xe9ent un d\xe9cor premium derri\xe8re les produits. \xc9clairage naturel lumineux combin\xe9 \xe0 une lumi\xe8re studio douce, ombres r\xe9alistes, profondeur de champ cin\xe9matographique, arri\xe8re-plan l\xe9g\xe8rement flou, reflets premium sur le marbre blanc poli.\\nStyle publicit\xe9 cosm\xe9tique haut de gamme, rendu hyper r\xe9aliste 8K, HDR, luxury skincare campaign, volumetric lighting, shallow depth of field, glossy reflections, condensation droplets, ultra sharp focus, cinematic product photography.","owner":"bassemdesigner.pro","upvotes":1,"downvotes":1,"upvoteDifference":0,"updatedAt":"2026-05-18T06:11:59.757Z"}')}}]);